svg.script:
(function () {
  var svg = document.currentScript.closest('svg');
  var q = function (c) { return svg.querySelector('.' + c); };
  var A = q('fig3-a'), B = q('fig3-b'), P = q('fig3-p'), PL = q('fig3-plabel'),
      INF = q('fig3-inf'), FILL = q('fig3-fill'), KNOB = q('fig3-knob'), HIT = q('fig3-hit'),
      BTN = q('fig3-btn'), PLAY = q('fig3-play'), PAUSE = q('fig3-pause');
  var x0 = -3.5, x1 = 4.5, y0 = -3.5, y1 = 4.5, S = 34, OX = 16, OY = 16;
  var TX0 = 95.0, TX1 = 243.0;
  var X = function (x) { return OX + (x - x0) * S; };
  var Y = function (y) { return OY + (y1 - y) * S; };

  // Segment of the line through (px, py) with direction (dx, dy), clipped to the window.
  function seg(el, px, py, dx, dy) {
    var t0 = -Infinity, t1 = Infinity;
    [[px, dx, x0, x1], [py, dy, y0, y1]].forEach(function (c) {
      if (Math.abs(c[1]) < 1e-12) return;
      var a = (c[2] - c[0]) / c[1], b = (c[3] - c[0]) / c[1];
      t0 = Math.max(t0, Math.min(a, b)); t1 = Math.min(t1, Math.max(a, b));
    });
    el.setAttribute('x1', X(px + dx * t0)); el.setAttribute('y1', Y(py + dy * t0));
    el.setAttribute('x2', X(px + dx * t1)); el.setAttribute('y2', Y(py + dy * t1));
  }

  var s = 0;
  function draw() {
    var kx = TX0 + (TX1 - TX0) * s;
    KNOB.setAttribute('x', kx - 6); FILL.setAttribute('width', kx - TX0);
    KNOB.setAttribute('aria-valuenow', Math.round(s * 100));
    if (s >= 0.999) {                       // at infinity: parallel lines, direction (1, 1)
      seg(A, 0, 1, 1, 1); seg(B, 1, 0, 1, 1);
      P.setAttribute('visibility', 'hidden'); PL.setAttribute('visibility', 'hidden');
      INF.setAttribute('visibility', 'visible');
      KNOB.setAttribute('aria-valuetext', 'at infinity: the lines are parallel');
      return;
    }
    var u = 1 / (1 - s);                    // s = 0 -> (1, 1); s -> 1 -> infinity
    seg(A, 0, 1, u, u - 1);                 // through (0, 1) and (u, u)
    seg(B, 1, 0, u - 1, u);                 // through (1, 0) and (u, u)
    INF.setAttribute('visibility', 'hidden');
    var inside = u <= x1 - 0.2;
    P.setAttribute('visibility', inside ? 'visible' : 'hidden');
    PL.setAttribute('visibility', inside ? 'visible' : 'hidden');
    P.setAttribute('cx', X(u)); P.setAttribute('cy', Y(u));
    PL.setAttribute('x', X(u) + 9); PL.setAttribute('y', Y(u) + 16);
    var v = (Math.round(u * 10) / 10).toString();
    PL.textContent = '(' + v + ',\u2009' + v + ')';
    KNOB.setAttribute('aria-valuetext', 'the lines meet at (' + v + ', ' + v + ')');
  }

  // Animation: sweep out to infinity and back. Starts playing unless the
  // reader prefers reduced motion; the button and the slider pause it.
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  // Timing: every key view holds still for HOLD ms (2 s, for diagrams this
  // intricate; see lesswrong.com/posts/ZiCvwLKreShtXuyiB), moves take MOVE ms.
  var MOVE = 3600, HOLD = 2000, T = 2 * (MOVE + HOLD), playing = false, visible = true, start = null;
  function phaseAt(t) {                              // t in ms, [0, T) -> s
    var e;
    if (t < MOVE) e = t / MOVE;                      // out
    else if (t < MOVE + HOLD) e = 1;                 // hold at infinity
    else if (t < 2 * MOVE + HOLD) e = 1 - (t - MOVE - HOLD) / MOVE;   // back
    else e = 0;                                      // hold at (1, 1)
    return 0.5 - 0.5 * Math.cos(Math.PI * e);        // ease
  }
  function frame(ts) {
    if (!playing) return;
    if (visible) {
      if (start === null) {
        // resume from the current position, heading outward
        var e = Math.acos(1 - 2 * s) / Math.PI;
        start = ts - e * MOVE;
      }
      s = phaseAt((ts - start) % T);
      draw();
    } else {
      start = null;
    }
    requestAnimationFrame(frame);
  }
  function setPlaying(on) {
    playing = on;
    PLAY.setAttribute('visibility', on ? 'hidden' : 'visible');
    PAUSE.setAttribute('visibility', on ? 'visible' : 'hidden');
    BTN.setAttribute('aria-label', on ? 'Pause animation' : 'Play animation');
    if (on) { start = null; requestAnimationFrame(frame); }
  }
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(function (es) { visible = es[0].isIntersecting; }).observe(svg);
  }
  function stop() { if (playing) setPlaying(false); }
  BTN.style.cursor = 'pointer';
  BTN.addEventListener('click', function () { setPlaying(!playing); });
  BTN.addEventListener('keydown', function (ev) {
    if (ev.key === 'Enter' || ev.key === ' ') { setPlaying(!playing); ev.preventDefault(); }
  });

  // Dragging and keyboard.
  function setFromEvent(ev) {
    var pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY;
    var x = pt.matrixTransform(svg.getScreenCTM().inverse()).x;
    s = Math.min(1, Math.max(0, (x - TX0) / (TX1 - TX0)));
    draw();
  }
  var dragging = false;
  [KNOB, HIT].forEach(function (el) {
    el.style.cursor = 'pointer';
    el.addEventListener('pointerdown', function (ev) {
      stop(); dragging = true; el.setPointerCapture(ev.pointerId); setFromEvent(ev); ev.preventDefault();
    });
    el.addEventListener('pointermove', function (ev) { if (dragging) setFromEvent(ev); });
    el.addEventListener('pointerup', function () { dragging = false; });
  });
  KNOB.addEventListener('keydown', function (ev) {
    var d = { ArrowRight: 0.05, ArrowUp: 0.05, ArrowLeft: -0.05, ArrowDown: -0.05 }[ev.key];
    if (ev.key === 'Home') d = -1; if (ev.key === 'End') d = 1;
    if (d === undefined) return;
    stop(); s = Math.min(1, Math.max(0, s + d)); draw(); ev.preventDefault();
  });
  draw();
  setPlaying(!reduce);
})();
